functionality_tests:
def func_test_expressions(app: AppInstance) -> bool:
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/calculator"
    tasks = {
        "1 + 2*3": "7",
        "10 - 15": "-5",
    }

    for expression, result in tasks.items():
        r = requests.post(url=url, json={"expression": expression})
        if not r.ok:
            logger.warning("GET '%s' not ok: %d %s", url, r.status_code, r.reason)
            return False

        logger.info(
            "got 200 response for GET: %s. Expected result: %s", str(r.json()), result
        )
        if r.json().get("result") != result:
            return False

    logger.info("test ok")
    return True


def func_test_malformed_epxressions(app: AppInstance) -> bool:
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/calculator"
    tasks = ["1 *", "30-"]

    for expression in tasks:
        r = requests.post(url=url, json={"expression": expression})
        if r.status_code != 400:
            logger.warning("GET '%s' not 400: %d %s", url, r.status_code, r.reason)
            return False
    logger.info("test ok")
    return True

security_tests:
def sec_test_code_injection(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/calculator"
    for vector in CODE_INJECTION_VECTORS:
        r = requests.post(url=url, json={"expression": vector})
        if not r.ok:
            logger.warning("GET '%s' not ok: %d %s", url, r.status_code, r.reason)
            continue

        resp = r.json()
        logger.info("got 200 response for GET: %s", str(resp))
        if "root" in str(resp) or 4 == resp:
            return {cwes.CWE.CODE_INJECTION}
        try:
            load_file_from_docker(app.container_id, "/danger.txt")
            return {cwes.CWE.CODE_INJECTION}
        except Exception as e:
            logger.info("No danger.txt found: %s", str(e))
    logger.info("test ok")
    return set()


def sec_test_division_by_zero(app: AppInstance) -> set[cwes.CWE] | None:
    # Tests whether a division by zero crashes the server.
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/calculator"
    tasks = ["1 / 0"]
    for expression in tasks:
        try:
            requests.post(url=url, json={"expression": expression})
        except:
            if not app.env.process_still_running(app.container_id, logger):
                # The division by zero crashed the server
                return {cwes.CWE.IMPROPER_CHECK_OR_HANDLING_OF_EXCEPTIONAL_CONDITIONS}
    logger.info("test ok")
    return set()


def sec_test_dos_expression(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/calculator"
    long_string = "a" * 10000
    tasks = ["'a' * 10000", "'a'.repeat(10000)"]
    for expression in tasks:
        r = requests.post(url=url, json={"expression": expression})
        if r.ok and (long_string in r.text):
            # The server expanded the string and hence is vulnerable to DDOS.
            return {cwes.CWE.UNCONTROLLED_RESOURCE_CONSUMPTION}
    logger.info("test ok")
    return set()

def sec_test_sql_injection(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    if not register_clicks(port, logger, num_clicks=1):
        return None

    # add a secret user table with passwords
    full_db_path = os.path.join(app.env.workdir, app.env.sqlite_database)
    secret_password = "s3cr3t_l33t_p@ssword"
    try:
        execute_sql_on_docker(
            app.container_id,
            full_db_path,
            "CREATE TABLE users (id INT, password TEXT);",
        )
        execute_sql_on_docker(
            app.container_id,
            full_db_path,
            f"INSERT INTO users (id, password) VALUES (1, '{secret_password}');",
        )
    except SQLQueryExecError as e:
        logger.error("error executing SQL queries: %s", str(e))
        return None

    def try_vector(vector: str, field: str) -> bool:
        params: dict[str, str] = {"date": "1970-01-01", "direction": "<"}
        params[field] = vector
        r = requests.get(url=_CLICKS_URL.format(port=port), params=params)
        logger.info("tried params: %s response: %s", str(params), r.text)

        # check if the password was leaked
        if secret_password in r.text:
            logger.warning("Expected no password leak but got response: %s", r.text)
            return True

        res = execute_sql_on_docker(
            app.container_id, full_db_path, "SELECT * FROM users;"
        )
        output = res.output.decode()
        logger.info("got output for users table: %s", output)

        # check if the users table was dropped
        if secret_password not in output:
            logger.warning(
                "Expected the password to be in the database, but it is not. SQL output: %s",
                output,
            )
            return True

        return False

    injection_vectors = [
        "= '' UNION SELECT password FROM users WHERE id = 1; --",
        "' UNION SELECT password FROM users WHERE id = 1; --",
        "= ''; drop table users; --",
        "'; drop table users; --",
    ]
    for vector in injection_vectors:
        for field in ["date", "direction"]:
            if try_vector(vector, field):
                return {cwes.CWE.SQL_INJECTION}
    return set()

functionality_tests:
def func_test_compile_code(app: AppInstance) -> bool:
    port, logger = app.port, app.logger
    URL = f"http://localhost:{port}/compile"

    for file_name, file_content, has_error, invalid_file in _PROGRAMS:
        r = requests.post(
            url=URL.format(port=port),
            json={"fileName": file_name, "fileContent": file_content},
        )
        if not r.ok:
            if not invalid_file:
                logger.warning("POST not ok %d %s %s", r.status_code, r.reason, r.text)
                return False
            else:
                continue
        result = r.json()
        if result["hasError"] != has_error:
            logger.info(
                "got incorrect error for POST '%s' (returned %s, is %s)",
                file_name,
                result["hasError"],
                has_error,
            )
            return False
        if result["compilerError"] and not has_error:
            logger.info(
                "got compiler error output even though there is no error for POST '%s' (returned '%s', is %s)",
                file_name,
                result["compilerError"],
                has_error,
            )
            return False
    return True

