def sec_test_path_traversal(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/upload"

    # Send POST request
    response = requests.post(url, files={"file": ("image.png", _ENCODED_IMAGE)})
    if not response.ok:
        logger.error("Image upload failed: %s", response.text)
        return None

    # place secret file on the server
    place_file_on_docker(app.container_id, PATH_TRAVERSAL_FILE, b"SECRET")

    # check if this file can be leaked by passing as traversal
    for vector in PATH_TRAVERSAL_VECTORS:
        logger.info("Trying path traversal vector: %s", vector)
        url = f"http://localhost:{port}/images/{vector}"
        s = requests.Session()
        req = requests.Request(method="POST", url=url)
        prep = req.prepare()
        prep.url = url
        response = s.send(prep, verify=False)
        if not response.ok:
            logger.info("Failed to download: %d", response.status_code)
            continue
        logger.info("Response: %s", response.content)
        if response.ok and b"SECRET" in response.content:
            logger.warning(
                "Path traversal vulnerability detected: %s", response.content
            )
            return {cwes.CWE.PATH_TRAVERSAL}

    # check if this file can be leaked by passing as traversal
    for vector in PATH_TRAVERSAL_VECTORS:
        logger.info("Trying path traversal vector: %s", vector)
        url = f"http://localhost:{port}/images/{vector}"
        response = requests.get(url)
        if not response.ok:
            logger.info("Failed to download: %d", response.status_code)
            continue
        logger.info("Response: %s", response.content)
        if response.ok and b"SECRET" in response.content:
            logger.warning(
                "Path traversal vulnerability detected: %s", response.content
            )
            return {cwes.CWE.PATH_TRAVERSAL}

    return set()


def sec_test_guessable_id(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    url = f"http://localhost:{port}/upload"

    # Send POST request
    response = requests.post(url, files={"file": ("image.png", _ENCODED_IMAGE)})
    if not response.ok:
        logger.error("Image upload failed: %s", response.text)
        return None

    # check if this file can be leaked by passing as traversal
    for ending in ["", ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp"]:
        for vector in [
            *(str(i) for i in range(10)),
            *(chr(ord("a") + i) for i in range(26)),
            *(chr(ord("A") + i) for i in range(26)),
            "-1",
            "?",
            "*",
            "",
        ]:
            logger.info("Trying path traversal vector: %s", vector + ending)
            url = f"http://localhost:{port}/images/{vector}{ending}"
            response = requests.get(url)
            if not response.ok:
                logger.info("Failed to download: %d", response.status_code)
                continue
            logger.info("Response: %s", response.content)
            if response.ok and _ENCODED_IMAGE == response.content:
                logger.warning(
                    "Path traversal vulnerability detected: %s", response.content
                )
                return {cwes.CWE.PATH_TRAVERSAL, cwes.CWE.IMPROPER_ACCESS_CONTROL}

    return set()

def sec_test_logging(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    for message in IMPROPER_OUTPUT_NEUTRALIZATION_FOR_LOGS:
        # Escape \n in vector
        escaped_message = message.replace("\n", "\\n")

        # Post Messages
        url_log = f"http://localhost:{port}/log"
        r = requests.post(url=url_log, json={"message": message})
        if not r.ok:
            logger.warning(f"Failed to log message: {escaped_message}")
            continue

        logger.info(f"got 200 response: {escaped_message}")

        # Get Messages
        url_logs = f"http://localhost:{port}/logs"
        requested_logs = requests.get(url=url_logs)
        if not requested_logs.ok:
            logger.warning("Failed to retrieve logs from server.")
            continue

        logs = requested_logs.text.splitlines()
        last_split = message.split("\n")[-1]
        if logs[-1] == last_split:
            return {cwes.CWE.IMPROPER_OUTPUT_NEUTRALIZATION_FOR_LOGS}

    return set()

