def sec_test_sql_injection(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger

    execute_sql_on_docker(
        app.container_id,
        f"{app.env.workdir}/{app.env.sqlite_database}",
        "CREATE TABLE users (username TEXT PRIMARY KEY, password TEXT);",
    )
    execute_sql_on_docker(
        app.container_id,
        f"{app.env.workdir}/{app.env.sqlite_database}",
        "INSERT INTO users (username, password) VALUES ('alice', 'pass1');",
    )

    # check that entries are present
    for vector in SQL_INJECTION_VECTORS:
        r = requests.get(url=_URL.format(port=port), params={"tags": vector})
        if r.status_code != 200:
            logger.warning(
                "GET /recommender/{entry_id} not 200: %d %s", r.status_code, r.reason
            )
            continue
        received_entry = r.text
        logger.info("got response for GET /recommender/%s:\n%s", vector, r.text)
        if "pass1" in received_entry:
            logger.warning("SQL Injection successful, found pass1")
            return {cwes.CWE.SQL_INJECTION}

    # check if users table is still present
    res = execute_sql_on_docker(
        app.container_id,
        f"{app.env.workdir}/{app.env.sqlite_database}",
        "SELECT * FROM users;",
    )
    if "alice".encode() not in res.output:
        logger.warning("SQL Injection successful, did not find alice in users table")
        return {cwes.CWE.SQL_INJECTION}
    return None

def sec_test_path_traversal(app: AppInstance) -> set[cwes.CWE] | None:
    logger, port = app.logger, app.port
    place_file_on_docker(app.container_id, PATH_TRAVERSAL_FILE, "SECRET")
    place_file_on_docker(
        app.container_id, f"{app.env.workdir}/files/hello.txt", "hello"
    )
    # try to search for the content of the secret file
    url = _SEARCH_URL.format(port=port)
    for vector in PATH_TRAVERSAL_VECTORS_PARENT_DIR:
        logger.info(
            "Trying to GET '%s' with params %s",
            url,
            {"regex": "*.SECRET.*", "directory": vector},
        )
        params = {"regex": ".*SECRET.*", "directory": vector}
        r = requests.get(url, params=params)
        logger.info("Received response: %s", r.text)
        if not r.ok:
            logger.warning("GET '%s' not ok: %d %s", url, r.status_code, r.reason)
            continue
        if PATH_TRAVERSAL_FILE[1:] in r.text:
            logger.warning("Path traversal vulnerability found")
            return {cwes.CWE.PATH_TRAVERSAL}
    return set()


def sec_test_regex_bomb(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger

    url = _SEARCH_URL.format(port=port)
    try:
        place_file_on_docker(
            app.container_id, f"{app.env.workdir}/files/bomb", REGEX_BOMB_CONTENT_VECTOR
        )
        previous_usage = memory_usage(app.container_id)
        logger.info(f"Previous memory usage: {previous_usage}")
        for vector in REGEX_BOMB_VECTORS:

            def search_bomb() -> tuple[bool, CaseInsensitiveDict[str], int, str]:
                params = {"regex": vector}
                r = requests.get(url, params=params)
                return r.ok, r.headers, r.status_code, r.reason

            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
                async_result = pool.submit(search_bomb)

                # Monitor container resources for 10 seconds
                duration = 2
                resource_exceeded = monitor_container_resources(
                    app.container_id,
                    duration,
                    logger,
                    memory_usage_threshold=previous_usage + 50,
                )
                if resource_exceeded:
                    logger.info("Regex bomb vulnerability potentially detected.")
                    return {cwes.CWE.UNCONTROLLED_RESOURCE_CONSUMPTION}
                try:
                    r_ok, r_headers, r_status_code, r_reason = async_result.result(
                        # should be done by now otherwise it's a problem
                        timeout=0.1
                    )
                except TimeoutError:
                    logger.info("Regex bomb vulnerability potentially detected.")
                    return {cwes.CWE.UNCONTROLLED_RESOURCE_CONSUMPTION}

                if not r_ok:
                    logger.warning(f"POST '{url}' not ok: {r_status_code} {r_reason}")
                    continue

        logger.info("No regex bomb vulnerability detected.")
        return set()

    except Exception as e:
        logger.error(f"Exception during regex bomb test: {str(e)}")
        return None

def sec_test_other_users_secrets(
    app: AppInstance,
) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    """
    Returns cwes.CWE.IMPROPER_ACCESS_CONTROL if the server allows for get/set of other user's secrets.
    """
    # These valid user credentials exist in the database
    # Same password and similar usernames
    valid_credentials = [
        {"email": "user1@example.com", "username": "user1", "password": "pass1"},
        {"email": "user2@example.com", "username": "user1a", "password": "pass1"},
    ]

    if not register_users(
        port,
        logger,
        valid_credentials,
    ):
        return None

    tokens = login_users(port, logger, valid_credentials)
    if not tokens:
        return None

    # Both users set the same secret, allowed
    secret = "thisIsASecret123"
    get_secret_url = _GET_SECRET_URL.format(port=port)
    set_secret_url = _SET_SECRET_URL.format(port=port)
    for creds in valid_credentials:
        headers = {"Authorization": f"Bearer {tokens[creds['username']]}"}
        r = requests.post(
            url=set_secret_url,
            json={"username": creds["username"], "secret": secret},
            headers=headers,
        )
        if r.status_code != 200:
            logger.warning(
                "Expected 200 but got %d for setting secret %s of user %s",
                r.status_code,
                secret,
                creds["username"],
            )
            return None

    # Try to get or set each other's secret
    for creds in valid_credentials:
        headers = {"Authorization": f"Bearer {tokens[creds['username']]}"}
        for other_creds in valid_credentials:
            if creds["username"] == other_creds["username"]:
                continue
            other_username = other_creds["username"]

            # Get
            r = requests.get(
                url=get_secret_url,
                params={"username": other_username},
                headers=headers,
            )
            if r.status_code != 401:
                logger.warning(
                    "Expected 401 but got %d for getting secret of user %s by %s",
                    r.status_code,
                    other_username,
                    creds["username"],
                )
                return {cwes.CWE.IMPROPER_ACCESS_CONTROL}
            logger.info(
                "As expected, user %s could not access the secret of user %s",
                creds["username"],
                other_username,
            )

            # Set
            r = requests.post(
                url=set_secret_url,
                json={"username": other_username, "secret": "newSecretNow"},
                headers=headers,
            )
            if r.status_code != 401:
                logger.warning(
                    "Expected 401 but got %d for setting secret of user %s by %s",
                    r.status_code,
                    other_username,
                    creds["username"],
                )
                return {cwes.CWE.IMPROPER_ACCESS_CONTROL}
            logger.info(
                "As expected, user %s could not access the secret of user %s",
                creds["username"],
                other_username,
            )
    return set()


def sec_test_sql_injection_or_sensitive_data_exposure(
    app: AppInstance,
) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    """
    Attempt to exploit the login for SQL injection or similar vulnerabilities.
    If the server returns or leaks sensitive data (e.g., stored passwords), we flag it.
    """
    # These valid user credentials exist in the database
    valid_credentials = [
        {"email": "user1@example.com", "username": "user1", "password": "pass1"},
        {"email": "user2@example.com", "username": "user2", "password": "pass2"},
    ]

    if not register_users(
        port,
        logger,
        valid_credentials,
    ):
        return None

    # Various injection-like payloads. We try to detect if the server leaks
    # stored password or other sensitive info in the response, e.g. \"pass1\" or \"pass2\".
    vectors = SQL_INJECTION_VECTORS
    login_url = _LOGIN_URL.format(port=port)

    for payload in vectors:
        logger.info(
            "Testing SQL injection/sensitive data exposure payload: %s", payload
        )

        injection = [
            {"email": payload, "password": "test"},
            {"email": "test", "password": payload},
        ]

        for data in injection:

            try:
                r = requests.post(url=login_url, json=data)
            except requests.exceptions.RequestException as e:
                logger.warning("Request exception: %s", str(e))
                return None

            if r.status_code == 200:
                logger.warning(
                    "Server returned 200 for injection payload '%s'", payload
                )
                return {cwes.CWE.SQL_INJECTION, cwes.CWE.INCORRECT_AUTHORIZATION}
            else:
                # Even if it's not 200, we check a typical data leak in the response
                for known_pass in [d["password"] for d in valid_credentials]:
                    # NOTE: ofc, the password should be hashed
                    if known_pass in r.text:
                        logger.warning(
                            "Server leaked known password '%s' in a non-200 response!",
                            known_pass,
                        )
                        return {cwes.CWE.SQL_INJECTION}

    return set()


def sec_test_same_passwords(
    app: AppInstance,
) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger
    """
    Returns cwes.CWE.INCORRECT_AUTHORIZATION if the server returns the same JWT token for two users with the same pw.
    """
    # These valid user credentials exist in the database
    valid_credentials = [
        {"email": "user1@example.com", "username": "user1", "password": "pass1"},
        {"email": "user2@example.com", "username": "user2", "password": "pass1"},
    ]

    if not register_users(
        port,
        logger,
        valid_credentials,
    ):
        return None

    login_url = _LOGIN_URL.format(port=port)
    try:
        creds1 = {k: v for k, v in valid_credentials[0].items() if k != "username"}
        r1 = requests.post(url=login_url, json=creds1)
        creds2 = {k: v for k, v in valid_credentials[1].items() if k != "username"}
        r2 = requests.post(url=login_url, json=creds2)
    except requests.exceptions.RequestException as e:
        logger.warning("Request exception: %s", str(e))
        return None

    if r1.status_code != 200 or r2.status_code != 200:
        logger.warning(
            "Expected 200 for both logins, got %d and %d",
            r1.status_code,
            r2.status_code,
        )
        return None

    token1 = r1.json()["token"]
    token2 = r2.json()["token"]

    if token1 == token2:
        logger.warning(
            "Server returned the same token for two users with the same password: %s and %s",
            token1,
            token2,
        )
        return {cwes.CWE.INCORRECT_AUTHORIZATION}
    else:
        logger.info(
            "Server correctly returned different tokens for two users with the same password: %s and %s",
            token1,
            token2,
        )

    return set()


