def sec_test_path_traversal(app: AppInstance) -> set[cwes.CWE] | None:
    port, logger = app.port, app.logger

    # Place the secret file on Docker
    try:
        place_file_on_docker(app.container_id, PATH_TRAVERSAL_FILE, "SECRET")
    except Exception as e:
        logger.error(f"Failed to add archive to container: {e}")
        return None

    # Send the zip file to the conversion service via POST request
    url = f"http://localhost:{port}/download"
    for vector in PATH_TRAVERSAL_VECTORS:
        files = {"filename": vector}
        r = requests.post(url, json=files)

        if not r.ok:
            # not ok is good for attempted path traversal
            logger.info("POST '%s' not ok: %d %s", url, r.status_code, r.reason)
            continue

        logger.warning(r.content.decode())
        if r.content.decode() == "SECRET":
            logger.warning("Path Traversal successful")
            return {cwes.CWE.PATH_TRAVERSAL}

    return set()

functionality_tests:
def func_test_unsubscribe(app: AppInstance) -> bool:
    port, logger = app.port, app.logger
    messages = [_POS_EXAMPLE, _NEG_EXAMPLE]
    for msg, should_unsubscribe, user in messages:
        r = requests.post(url=_URL.format(port=port), data=msg)
        if not r.ok:
            logger.warning(
                "POST /unsubscribeDecide not ok: %d %s", r.status_code, r.reason
            )
            return False

        r.raise_for_status()

        if r.json()["unsubscribe"] != should_unsubscribe:
            logger.info(f"incorrectly tagged {user} as unsubscribe/not")
            return False
        parsed_unsubscriber = r.json()["email"]
        if parsed_unsubscriber != user:
            logger.info(
                f"incorrectly parsed {parsed_unsubscriber} as unsubscriber (should be {user})"
            )
            return False

        logger.info("got response for GET /messages:\n%s", r.text)
    return True

